export const CRASH_GAME_HTML = "<!doctype html>\n<html lang=\"fr\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#081024\">\n  <meta name=\"description\" content=\"Prototype mobile de l’interface Aviator recréée depuis la maquette vidéo.\">\n  <title>Aviator — jeu</title>\n  <style>:root{font-family:Roboto,Arial,sans-serif;color:#f5f6fa;background:#070e21;font-synthesis:none;text-rendering:optimizeLegibility;--navy:#080f23;--panel:#10172e;--panel2:#1b2347;--orange:#f0500b;--orange2:#f27417;--gold:#ffd34a;--white:#f7f7fa}\n*{box-sizing:border-box}\nhtml,body{margin:0;min-height:100%;background:#070e21}\nbody{overflow-x:hidden;-webkit-font-smoothing:antialiased}\nbutton,input{font:inherit}\nbutton{color:inherit;cursor:pointer}\n.app-shell{width:100%;max-width:540px;margin:0 auto;min-height:100vh;background:#080f23;overflow:hidden}\n.topbar{height:40px;background:#fafafa;display:flex;align-items:center;justify-content:space-between;padding:0 22px;color:#46515b;position:relative;z-index:2}\n.icon-button{border:0;background:transparent;display:grid;place-items:center;padding:0;color:#73878c}\n.icon-button svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}\n.back-button{width:20px;height:28px;margin-left:0}\n.settings-button{width:25px;height:29px;margin-right:0}\n.settings-button svg{width:24px;height:24px;stroke:#7e9196;stroke-width:1.65;stroke-dasharray:2.2 1.2}\n.wallet{position:absolute;left:50%;top:4px;transform:translateX(-50%);height:31px;display:flex;align-items:center;gap:4px;background:#d2d2d2;border-radius:15px;padding:4px 5px;color:white;box-shadow:inset 0 1px 2px #f3f4f7}\n.wallet #balance{font-size:11.5px;line-height:1;font-weight:500;letter-spacing:.1px;background:#a7a8ab;color:#f1f1f1;border-radius:10px;padding:6px 7px;white-space:nowrap;text-align:center}\n.wallet-plus{width:24px;height:23px;flex:none;display:grid;place-items:center;background:#b4d9b6;border-radius:7px}\n.wallet-plus svg{width:14px;height:14px;fill:none;stroke:#fff;stroke-width:2.6;stroke-linecap:round;pointer-events:none}\n.subnav{height:36px;display:grid;grid-template-columns:1fr 1.25fr;gap:6px;padding:10px 9px 0}\n.tab{height:25px;border-radius:6px;font-size:13px;line-height:1;text-transform:uppercase;font-weight:500}\n.rules-tab{border:1px solid #dc5c24;background:transparent;color:#e67936;text-transform:none;font-size:13px}\n.history-tab{border:0;background:linear-gradient(105deg,#f27713,#df263c);color:#fff}\n.history-tab.history-selected{filter:brightness(1.12)}\n.history-clock{font-size:16px;vertical-align:-1px;margin-right:3px}\n.game-scene{height:154px;position:relative;background-color:#080f23;background-image:radial-gradient(ellipse at 54% 45%,rgba(37,46,90,.25),transparent 58%),linear-gradient(180deg,#0a1027,#081024);overflow:hidden}\n.flight-chart{position:absolute;inset:0;width:100%;height:100%}\n.countdown-indicator-overlay{position:absolute;inset:0;width:100%;height:100%;overflow:hidden;pointer-events:none;z-index:2}\n.chart-grid path{stroke:rgba(133,145,189,.22);stroke-width:1;stroke-dasharray:1 4}\n.chart-grid path:last-child{stroke-dasharray:none;stroke:rgba(190,194,212,.12)}\n.chart-dots circle{fill:#82879e;opacity:.72}\n.multiplier{font-size:37px;font-weight:700;letter-spacing:-1.5px;fill:#f5f5f8}\n.countdown-text{font-size:36px;font-weight:700;fill:#f8f8fb}\n.countdown-text[hidden]{display:none}\n.countdown-accepted{position:absolute;z-index:1;left:14%;right:14%;top:39%;min-height:31px;display:flex;align-items:center;justify-content:center;padding:5px 8px;border:1px solid rgba(148,218,75,.22);border-radius:4px;background:rgba(6,12,29,.93);color:#a2f653;font-size:14px;font-weight:500;text-align:center;letter-spacing:.01em;text-shadow:0 0 7px rgba(160,244,81,.16)}\n.countdown-accepted[hidden]{display:none}\n.countdown-segment{opacity:.34;transition:opacity .18s ease}\n.countdown-active-bar{stroke:#f05b20;stroke-width:5.8;stroke-linecap:round;filter:drop-shadow(0 0 3px rgba(240,91,32,.55))}\n.crash-flare{opacity:0;transform-box:fill-box;transform-origin:center}\n.game-scene.is-crashed .crash-flare{opacity:1;animation:flare .7s ease-out infinite alternate}\n.game-scene.is-crashed #plane,.game-scene.is-countdown #plane{opacity:0}\n.game-scene.is-countdown #flight-trail{opacity:.08}\n.game-notice{position:absolute;left:5%;right:5%;top:16px;text-align:center;min-height:21px;line-height:21px;font-size:12px;color:#80ef74;text-shadow:0 1px 3px #071018}\n.game-notice.success{color:#7bec69}.game-notice.danger{color:#fff;background:rgba(190,38,49,.84);border-radius:3px;padding:2px 4px}\n@keyframes flare{from{transform:scale(.8);filter:brightness(.9)}to{transform:scale(1.3);filter:brightness(1.3)}}\n.bets-area{padding:11px 4px 0;background:#080f23}\n.bet-cards{display:flex;flex-direction:column;gap:14px}\n.bet-card{position:relative;display:grid;grid-template-columns:minmax(0,1.56fr) minmax(108px,.87fr) 24px;grid-template-rows:34px 62px;gap:6px 7px;padding:9px 7px 9px 12px;min-height:120px;background:#10172d;border-radius:6px;box-shadow:0 2px 7px rgba(0,0,0,.22)}\n.bet-input-wrap{grid-column:1;grid-row:1;position:relative}\n.bet-input{width:100%;height:34px;border:0;border-radius:4px;background:#fff;color:#151820;padding:0 34px 0 10px;font-size:15px;font-weight:500;outline:none}\n.clear-input{position:absolute;right:7px;top:4px;width:25px;height:26px;background:none;border:0;color:#171923;font-size:22px;line-height:20px;padding:0}\n.auto-toggle{grid-column:2;grid-row:1;border:1px solid #6a4b36;border-radius:5px;background:#171a2a;color:#e08442;font-size:12px;line-height:14px;font-weight:700;text-align:center;text-transform:uppercase;padding:2px 3px}\n.remove-bet{grid-column:3;grid-row:1;border:0;border-radius:5px;background:#242a46;color:#fff;font-size:21px;line-height:1;padding:0;height:25px}\n.quick-bets{grid-column:1;grid-row:2;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-template-rows:repeat(2,1fr);gap:5px}\n.quick-bet{border:0;border-radius:4px;background:#252c53;color:#f1f2f8;font-size:14px;font-weight:500;padding:0 2px;box-shadow:0 1px 2px #0a0d18}\n.action-button{grid-column:2/4;grid-row:2;border:0;border-radius:5px;background:linear-gradient(110deg,#f36c12,#ef4c08);color:#fff;font-size:13px;font-weight:700;line-height:15px;text-align:center;padding:5px 7px;text-transform:uppercase}\n.action-button small{display:block;font-size:10px;font-weight:400;text-transform:none;line-height:13px}\n.action-button.queued{background:#bb5b1a;color:#f3d4ba}\n.action-button.cashout{background:linear-gradient(110deg,#f8d848,#f8b321);color:#342507}\n.action-button.cashed,.action-button.disabled{background:#55586b;color:#dfdfe4}\n.win-notice{position:absolute;right:7px;bottom:73px;padding:3px 7px;background:#f1c837;border-radius:3px;color:#27200c;font-size:10px;font-weight:700;z-index:1;white-space:nowrap}\n.add-bet{display:flex;align-items:center;justify-content:center;gap:5px;width:min(60%,234px);height:35px;margin:9px auto 0;border:0;border-radius:4px;background:#292e56;color:#f7f7fb;font-size:14px;font-weight:700;letter-spacing:.2px}\n.add-bet span{font-size:23px;font-weight:400;line-height:1}\n.add-bet[hidden]{display:none}\n.stats-bar{height:59px;margin:10px 4px 0;border-radius:5px;background:linear-gradient(100deg,#ef7918 0%,#eb4c19 55%,#c72d40 100%);display:grid;grid-template-columns:repeat(3,1fr);align-items:center;text-align:center;color:#fff;padding:2px 3px}\n.stat{display:flex;min-width:0;flex-direction:column;align-items:center;justify-content:center;gap:2px;line-height:14px}\n.stat>span{font-size:12px;font-weight:400;white-space:nowrap}\n.stat strong{font-size:12px;font-weight:700;display:flex;align-items:center;justify-content:center;flex-wrap:wrap;column-gap:2px;line-height:13px;max-width:100%}\n.stat small{flex-basis:100%;font-size:11px;font-weight:600;line-height:10px}\n.stat-icon{width:10px;height:10px;fill:#fff;opacity:.95;flex:none}\n.stat-icon:nth-of-type(2){fill:none;stroke:#fff;stroke-width:1}\n.demo-data-note{margin:4px 8px 0;color:#9ca2b8;font-size:9px;line-height:12px;text-align:center}\n.leaderboard{padding:0 7px 18px;background:#080f23}\n.table-head,.bet-row{display:grid;grid-template-columns:1.32fr .9fr 1.15fr .65fr;align-items:center;column-gap:4px}\n.table-head{height:27px;color:#818398;font-size:10px;font-weight:500;white-space:nowrap;border-bottom:1px solid rgba(101,108,143,.2)}\n.table-head span:first-child{overflow:hidden;text-overflow:ellipsis}\n.bet-row{height:24px;color:#e8e9f0;font-size:10px;font-weight:400;white-space:nowrap}\n.bet-row span{overflow:hidden;text-overflow:clip}\n.bet-row .positive{color:#77d768}\n.bet-row .amount{text-align:left}\n.bet-row .gain{text-align:right;padding-right:1px}\n.bet-row.player-live{color:#d8d9e4}\n.bet-row.player-cashed{color:#e8f6e5}\n.bet-row.player-cashed .gain{color:#77d768}\n.bet-row.player-lost{color:#777c91;opacity:.72}\n.modal-layer{position:fixed;z-index:20;inset:0;display:flex;align-items:center;justify-content:center;padding:16px 4px}\n.modal-layer[hidden],.modal[hidden]{display:none}\n.modal-backdrop{position:absolute;inset:0;background:rgba(0,0,0,.79)}\n.modal{position:relative;z-index:1;width:min(100%,360px);border-radius:20px;background:linear-gradient(145deg,#1b2343 0%,#18213d 100%);box-shadow:0 18px 45px rgba(0,0,0,.46);color:#f7f7fb;transform:translateY(20px)}\n.modal-close{position:absolute;right:15px;top:8px;width:27px;height:29px;border:0;background:transparent;color:#fff;font-size:32px;font-weight:300;line-height:24px;padding:0}\n.modal h1{text-align:center;margin:27px 31px 20px;font-size:22px;line-height:1.15;font-weight:700;letter-spacing:.2px;white-space:nowrap}\n.rules-modal{width:min(calc(100vw - 54px),346px);padding:0 15px 24px;border-radius:19px;transform:translateY(22px)}\n.rules-modal h1{font-size:25px;margin-top:26px;margin-bottom:26px}\n.rules-list{margin:0;padding-left:19px;font-size:13.5px;line-height:1.14;font-weight:400}\n.rules-list li{padding-left:2px;margin:0 0 6px}\n.rules-list li:last-child{margin-bottom:0}\n.auto-modal{width:min(calc(100vw - 36px),360px);padding:0 23px 22px;border-radius:19px;transform:translate(-16px,23px)}\n.auto-modal h1{margin:22px 22px 17px;font-size:17px}\n#auto-form{display:block;transform:translateY(0)}\n.field-label{display:block;color:#b7bac8;font-size:13px;line-height:16px;margin:0 0 4px}\n.modal-input-wrap{height:33px;display:flex;align-items:center;background:#fff;border-radius:4px;margin-bottom:13px;padding-left:11px}\n#auto-form>.modal-input-wrap:nth-of-type(2){margin-bottom:14px}\n.modal-input-wrap input{min-width:0;flex:1;height:100%;border:0;outline:0;background:transparent;color:#17191f;font-size:14px;font-weight:500}\n.modal-input-wrap input::placeholder{color:#94969d;opacity:1;font-weight:400}\n.modal-input-wrap input::-webkit-outer-spin-button,.modal-input-wrap input::-webkit-inner-spin-button{-webkit-appearance:none;margin:0}\n.modal-input-wrap input[type=number]{appearance:textfield;-moz-appearance:textfield}\n.modal-input-wrap button{width:35px;height:100%;border:0;background:transparent;color:#1b1c21;font-size:24px;line-height:1}\n.auto-options{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:16px}\n.option-group{border:0;margin:0;padding:0;min-width:0}\n.option-group legend{padding:0;margin:0 0 7px;font-size:13px;font-weight:700;line-height:16px;white-space:nowrap}\n.wins-group legend{color:#a8ef42}.losses-group legend{color:#f33343}\n.option-group label{display:grid;grid-template-columns:20px 1fr;align-items:start;gap:5px;min-height:28px;color:#f5f5f8;font-size:13px;line-height:13px;margin-bottom:1px}\n.option-group input{appearance:none;width:19px;height:19px;border:1.5px solid #8990a5;border-radius:50%;margin:0;position:relative;background:transparent}\n.option-group input::after{content:\"\";position:absolute;inset:4px;border-radius:50%;background:transparent}\n.wins-group input:checked{border-color:#8fe435}.wins-group input:checked::after{background:#8fe435}\n.losses-group input:checked{border-color:#e43848}.losses-group input:checked::after{background:#e43848}\n.auto-submit{width:100%;height:37px;margin-top:17px;border:0;border-radius:4px;background:linear-gradient(100deg,#f17514,#ef4d0b);color:#fff;font-size:13px;font-weight:700}\n.toast-message{position:fixed;z-index:30;left:50%;top:52px;transform:translateX(-50%);padding:7px 12px;border-radius:3px;background:#257b2f;color:#e8ffe5;font-size:12px;white-space:nowrap;box-shadow:0 2px 9px #0008}\n@media(max-width:360px){.topbar{padding:0 15px}.bet-card{grid-template-columns:minmax(0,1.3fr) minmax(102px,.9fr) 23px;padding-left:8px;column-gap:5px}.auto-toggle{font-size:10px}.quick-bet{font-size:12px}.action-button{font-size:11px;padding-left:3px;padding-right:3px}.rules-list{font-size:12.5px}.auto-modal{padding-left:17px;padding-right:17px}.option-group label{font-size:11.5px;grid-template-columns:18px 1fr;gap:3px}}\n@media(min-width:540px){.app-shell{box-shadow:0 0 30px #0008}.modal-layer{padding:18px}}\n\n/* Corrections de fidélité relevées par comparaison directe avec les frames vidéo. */\n.chart-grid path{stroke:rgba(169,178,208,.28);stroke-width:1;stroke-dasharray:2 5}\n.chart-grid path:last-child{stroke:rgba(194,200,218,.22);stroke-dasharray:none}\n.game-scene.is-countdown #multiplier{display:none}\n.game-scene.is-countdown #flight-trail{opacity:0}\n.game-notice{left:5%;right:5%;top:62px;min-height:30px;line-height:30px;font-size:13px;text-shadow:none}\n.game-notice.success{left:25%;right:25%;color:#9bf15f;background:rgba(8,12,28,.94);border:1px solid rgba(57,65,95,.55);border-radius:5px;padding:0 5px;white-space:nowrap}\n.game-notice.success-early{left:5%;right:5%;top:16px;min-height:21px;line-height:21px;color:#80ef74;background:transparent;border:0;border-radius:0;padding:0;text-shadow:0 1px 3px #071018}\n.game-notice.danger{left:5%;right:5%;top:62px;min-height:30px;line-height:30px;background:rgba(190,38,49,.9);border-radius:4px;padding:0 6px}\n.app-shell.reference-dim{filter:none}\n.bet-card.active-bet .bet-input{background:#bfc1c5;color:#171820}\n.bet-card.active-bet .quick-bet{filter:brightness(.73)}\n.bet-card.active-bet .remove-bet{filter:none}\n.remove-bet[hidden]{display:none}\n.action-button.queued{background:#78651f;color:#d7c996}\n.action-button.cashout{background:#ff9700;color:#fff}\n.rules-modal{transform:translateY(23px)}\n.auto-modal{padding-bottom:29px;transform:translate(-16px,22px)}\n/* Le crash utilise le sprite capturé dans la vidéo, sans effet dessiné différent. */\n.game-scene.is-crashed .crash-flare{animation:impact-burst .8s ease-in-out infinite alternate;filter:brightness(1.16) saturate(1.14) drop-shadow(0 0 5px rgba(219,133,66,.45))}\n@keyframes impact-burst{from{opacity:.86}to{opacity:1}}\n\nbutton:disabled{opacity:.55;cursor:default}\n</style>\n</head>\n<body>\n  <div class=\"app-shell\">\n    <header class=\"topbar\" aria-label=\"Barre de navigation\">\n      <button class=\"icon-button back-button\" type=\"button\" aria-label=\"Retour\">\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m15 4-8 8 8 8\"/></svg>\n      </button>\n      <div class=\"wallet\" aria-label=\"Solde\">\n        <span id=\"balance\">Connexion…</span>\n        <span class=\"wallet-plus\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" focusable=\"false\"><path d=\"M12 5v14M5 12h14\"/></svg></span>\n      </div>\n      <button class=\"icon-button settings-button\" type=\"button\" aria-label=\"Paramètres\">\n        <svg viewBox=\"0 0 28 28\" aria-hidden=\"true\"><path d=\"M14 3.5 16 4l1.1 2.3 2.5.7 2.1-1 1.4 1.5-.9 2.3 1.3 2.3 2.1.8v2.2l-2.2.9-.8 2.4.9 2.1-1.5 1.6-2.3-.9-2.2 1.3-.9 2.2h-2.2l-.9-2.2-2.4-.8-2.2.9-1.5-1.5.9-2.3-1.2-2.2-2.3-.9v-2.2l2.3-.9.8-2.4-.9-2.2L7 6.1l2.3.9 2.2-1.2.9-2.3z\"/><circle cx=\"14\" cy=\"14\" r=\"4\"/></svg>\n      </button>\n    </header>\n\n    <nav class=\"subnav\" aria-label=\"Navigation du jeu\">\n      <button class=\"tab rules-tab\" id=\"open-rules\" type=\"button\">Règles</button>\n      <button class=\"tab history-tab\" id=\"history-tab\" type=\"button\"><span class=\"history-clock\" aria-hidden=\"true\">◴</span> HISTORIQUE</button>\n    </nav>\n\n    <main>\n      <section class=\"game-scene\" aria-label=\"Écran de jeu Aviator\">\n        <svg class=\"flight-chart\" viewBox=\"0 0 400 160\" preserveAspectRatio=\"none\" aria-hidden=\"true\">\n          <defs>\n            <linearGradient id=\"trailFade\" x1=\"0\" y1=\"1\" x2=\"1\" y2=\"0\"><stop offset=\"0\" stop-color=\"#f5d743\"/><stop offset=\"1\" stop-color=\"#ffe94a\"/></linearGradient>\n            <linearGradient id=\"hills-back\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#33416f\" stop-opacity=\".2\"/><stop offset=\"1\" stop-color=\"#101a3b\" stop-opacity=\".05\"/></linearGradient>\n            <linearGradient id=\"hills-front\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#26345f\" stop-opacity=\".22\"/><stop offset=\"1\" stop-color=\"#0c1534\" stop-opacity=\".04\"/></linearGradient>\n          </defs>\n          <g class=\"chart-hills\" aria-hidden=\"true\">\n            <path d=\"M18 135 C48 124 61 108 90 110 C117 112 129 98 154 83 C182 65 202 92 223 108 C252 129 279 112 305 96 C336 76 355 84 378 101 C387 108 394 106 400 103 V158 H18Z\" fill=\"url(#hills-back)\"/>\n            <path d=\"M18 144 C51 135 66 124 91 126 C118 129 144 113 166 105 C192 95 208 115 229 126 C253 139 281 127 309 119 C339 110 361 119 382 131 C389 135 395 136 400 133 V158 H18Z\" fill=\"url(#hills-front)\"/>\n          </g>\n          <g class=\"chart-grid\">\n            <path d=\"M18 25H395 M18 55H395 M18 85H395 M18 115H395 M18 145H395\"/>\n            <path d=\"M18 18V151\"/>\n          </g>\n          <g class=\"chart-dots chart-dots-y\" id=\"chart-dots-y\"></g>\n          <g class=\"chart-dots chart-dots-x\" id=\"chart-dots-x\"></g>\n          <path id=\"flight-trail\" d=\"M18 126 C70 124 125 99 158 77\" fill=\"none\" stroke=\"url(#trailFade)\" stroke-width=\"2.4\" stroke-linecap=\"round\"/>\n          <image id=\"plane\" href=\"data:image/png;base64,\" x=\"-30\" y=\"-17\" width=\"59\" height=\"33\" preserveAspectRatio=\"none\" transform=\"translate(158 77)\"/>\n          <image id=\"crash-flare\" class=\"crash-flare\" href=\"data:image/png;base64,\" x=\"-37\" y=\"-24\" width=\"75\" height=\"60\" preserveAspectRatio=\"none\" transform=\"translate(18 126)\" aria-hidden=\"true\"/>\n          <g id=\"countdown-spinner\" class=\"countdown-spinner\" display=\"none\" fill=\"#fff\" stroke=\"#fff\" stroke-width=\"4.5\" stroke-linecap=\"round\" aria-hidden=\"true\">\n            <path id=\"countdown-segment-1\" class=\"countdown-segment\" d=\"M290 114l7-1\"/>\n            <path id=\"countdown-segment-2\" class=\"countdown-segment\" d=\"M312.3 43l5.4 6\"/>\n            <path id=\"countdown-segment-3\" class=\"countdown-segment\" d=\"M347.1 25l1.8 8\"/>\n            <path id=\"countdown-segment-4\" class=\"countdown-segment\" d=\"M387 27l-2 8\"/>\n            <circle cx=\"309\" cy=\"113\" r=\"4.1\" stroke=\"none\"/>\n          </g>\n          <text id=\"countdown\" class=\"countdown-text\" x=\"385\" y=\"112\" text-anchor=\"end\" hidden>4</text>\n          <text id=\"multiplier\" class=\"multiplier\" x=\"386\" y=\"123\" text-anchor=\"end\">1.49x</text>\n        </svg>\n        <svg id=\"countdown-indicator-overlay\" class=\"countdown-indicator-overlay\" viewBox=\"0 0 400 160\" preserveAspectRatio=\"none\" aria-hidden=\"true\" display=\"none\">\n          <path id=\"countdown-active-bar\" class=\"countdown-active-bar\" d=\"M-6 0L6 0\" transform=\"translate(386 31) rotate(108)\"/>\n        </svg>\n        <div id=\"countdown-accepted\" class=\"countdown-accepted\" hidden aria-live=\"polite\">Votre pari est accepté !</div>\n        <div class=\"game-notice\" id=\"game-notice\" aria-live=\"polite\" hidden></div>\n      </section>\n\n      <section class=\"bets-area\" aria-label=\"Paris\">\n        <div class=\"bet-cards\" id=\"bet-cards\"></div>\n        <button class=\"add-bet\" id=\"add-bet\" type=\"button\"><span aria-hidden=\"true\">＋</span> AJOUTER UN PARI</button>\n      </section>\n\n      <section class=\"stats-bar\" aria-label=\"Statistiques de la partie\">\n        <div class=\"stat\"><span>Nombre de paris</span><strong><svg class=\"stat-icon\" viewBox=\"0 0 12 12\" aria-hidden=\"true\"><circle cx=\"6\" cy=\"3\" r=\"2\"/><path d=\"M2 11V8a4 4 0 0 1 8 0v3z\"/></svg><b id=\"bet-count\">2436</b></strong></div>\n        <div class=\"stat\"><span>Total des paris</span><strong><svg class=\"stat-icon\" viewBox=\"0 0 12 12\" aria-hidden=\"true\"><ellipse cx=\"4\" cy=\"3\" rx=\"2.8\" ry=\"1.5\"/><path d=\"M1.2 3v4c0 .9 1.2 1.5 2.8 1.5M6.8 3v1.8\"/><ellipse cx=\"8\" cy=\"6\" rx=\"2.8\" ry=\"1.5\"/><path d=\"M5.2 6v3.4c0 .9 1.2 1.5 2.8 1.5s2.8-.6 2.8-1.5V6\"/></svg><b id=\"total-bets\">1781268.6</b><small> XAF</small></strong></div>\n        <div class=\"stat\"><span>Gains totaux</span><strong><svg class=\"stat-icon\" viewBox=\"0 0 12 12\" aria-hidden=\"true\"><path d=\"M6 1 7.3 3.7l3 .4-2.2 2.1.5 3-2.6-1.4-2.6 1.4.5-3-2.2-2.1 3-.4z\"/><path d=\"M3.5 10.4h5\"/></svg><b id=\"total-wins\">37282.44</b><small> XAF</small></strong></div>\n      </section>\n      <p class=\"demo-data-note\" role=\"note\">Statistiques et joueurs de démonstration — ne reflètent pas les mises du compte.</p>\n\n      <section class=\"leaderboard\" aria-label=\"Liste des paris\">\n        <div class=\"table-head\" role=\"row\">\n          <span>NOM D'UTILISAT...</span><span>COTE</span><span>PARI</span><span>GAIN</span>\n        </div>\n        <div id=\"bet-rows\" class=\"bet-rows\"></div>\n      </section>\n    </main>\n  </div>\n\n  <div class=\"modal-layer\" id=\"modal-layer\" hidden>\n    <div class=\"modal-backdrop\" data-close-modal></div>\n    <section class=\"modal rules-modal\" id=\"rules-modal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"rules-title\" hidden>\n      <button class=\"modal-close\" type=\"button\" aria-label=\"Fermer\" data-close-modal>×</button>\n      <h1 id=\"rules-title\">COMMENT JOUER ?</h1>\n      <ol class=\"rules-list\">\n        <li>Placez un pari. La mise initiale est déterminée avant le début du jeu.</li>\n        <li>La mise maximale est de 358548.65 XAF et la mise minimale est de 200 XAF.</li>\n        <li>Dès le début de chaque tour, la cote commence à augmenter jusqu’au crash.</li>\n        <li>Si vous arrivez à cliquer sur le bouton « Récupérer les gains » avant le crash, votre mise sera alors multipliée par la cote indiquée.</li>\n        <li>Le crash survient de façon aléatoire, mais plus vous restez longtemps dans le jeu, plus la cote sera élevée et plus vous gagnerez.</li>\n        <li>Si vous n’avez pas récupéré vos gains au moment du crash, le jeu s’arrête et votre mise est perdue.</li>\n      </ol>\n    </section>\n\n    <section class=\"modal auto-modal\" id=\"auto-modal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"auto-title\" hidden>\n      <button class=\"modal-close\" type=\"button\" aria-label=\"Fermer\" data-close-modal>×</button>\n      <h1 id=\"auto-title\">JEU AUTOMATIQUE</h1>\n      <form id=\"auto-form\">\n        <label class=\"field-label\" for=\"base-bet\">Pari de base</label>\n        <div class=\"modal-input-wrap\"><input id=\"base-bet\" type=\"number\" value=\"400\" min=\"200\"><button type=\"button\" data-clear=\"base-bet\" aria-label=\"Effacer\">×</button></div>\n        <label class=\"field-label\" for=\"max-bet\">Montant de mise max.</label>\n        <div class=\"modal-input-wrap\"><input id=\"max-bet\" type=\"number\" placeholder=\"Saisissez le montant\"><button type=\"button\" data-clear=\"max-bet\" aria-label=\"Effacer\">×</button></div>\n        <label class=\"field-label\" for=\"auto-cashout\">Encaissement auto (≥ 1.01)</label>\n        <div class=\"modal-input-wrap\"><input id=\"auto-cashout\" type=\"number\" min=\"1.01\" step=\"0.01\" placeholder=\"Saisissez la cote\"><button type=\"button\" data-clear=\"auto-cashout\" aria-label=\"Effacer\">×</button></div>\n        <div class=\"auto-options\">\n          <fieldset class=\"option-group wins-group\">\n            <legend>SI VOUS GAGNEZ</legend>\n            <label><input type=\"radio\" name=\"win-choice\" value=\"base\" checked><span>Retour à la mise de base</span></label>\n            <label><input type=\"radio\" name=\"win-choice\" value=\"double\"><span>Doublez votre mise</span></label>\n          </fieldset>\n          <fieldset class=\"option-group losses-group\">\n            <legend>SI VOUS PERDEZ</legend>\n            <label><input type=\"radio\" name=\"loss-choice\" value=\"base\" checked><span>Retour à la mise de base</span></label>\n            <label><input type=\"radio\" name=\"loss-choice\" value=\"double\"><span>Doublez votre mise</span></label>\n          </fieldset>\n        </div>\n        <button class=\"auto-submit\" type=\"submit\">PLACER UN PARI AUTO</button>\n      </form>\n    </section>\n  </div>\n\n  <script>window.__CRASH_GAME_ASSETS__={\"plane\":\"data:image/png;base64,\",\"crashSprite\":\"data:image/png;base64,\",\"crashFlare\":\"data:image/png;base64,\",\"crashFrames\":[\"data:image/png;base64,\",\"data:image/png;base64,\",\"data:image/png;base64,\",\"data:image/png;base64,\",\"data:image/png;base64,\",\"data:image/png;base64,\",\"data:image/png;base64,\",\"data:image/png;base64,\",\"data:image/png;base64,\"]};\n/* Bridge strict: aucune balance locale de secours, toutes les écritures passent par l’application hôte. */\n(function attachAviatorWalletBridge(global) {\n  const pending = new Map();\n  const listeners = new Set();\n  const crashTargetListeners = new Set();\n  let sequence = 0;\n\n  function normalizeBalance(snapshot) {\n    const amount = Number(snapshot && snapshot.amount);\n    if (!Number.isFinite(amount) || amount < 0) throw new Error('Solde reçu invalide.');\n    return { amount, currency: snapshot.currency || 'XAF' };\n  }\n\n  function sendToHost(message) {\n    if (global.ReactNativeWebView && typeof global.ReactNativeWebView.postMessage === 'function') {\n      global.ReactNativeWebView.postMessage(JSON.stringify(message));\n      return;\n    }\n    if (global.parent && global.parent !== global) {\n      global.parent.postMessage({ __onexGameMessage: message }, '*');\n      return;\n    }\n    throw new Error('Connexion au portefeuille hôte indisponible.');\n  }\n\n  function request(operation, payload = {}) {\n    return new Promise((resolve, reject) => {\n      const id = `crash-wallet-${Date.now().toString(36)}-${++sequence}`;\n      const timeout = global.setTimeout(() => {\n        pending.delete(id);\n        reject(new Error('Le portefeuille ne répond pas.'));\n      }, 10000);\n      pending.set(id, { resolve, reject, timeout });\n      try {\n        sendToHost({ type: 'wallet_request', id, operation, payload });\n      } catch (error) {\n        global.clearTimeout(timeout);\n        pending.delete(id);\n        reject(error);\n      }\n    });\n  }\n\n  function validateBet(payload, needsAmount) {\n    if (!payload || typeof payload.requestId !== 'string' || !payload.requestId.trim()) {\n      throw new Error('Identifiant de transaction manquant.');\n    }\n    if (!String(payload.roundId || '').trim() || !String(payload.betId || '').trim()) {\n      throw new Error('Identifiant du pari manquant.');\n    }\n    if (needsAmount && (!Number.isFinite(Number(payload.amount)) || Number(payload.amount) <= 0)) {\n      throw new Error('Montant de transaction invalide.');\n    }\n  }\n\n  const bridge = {\n    mode: 'host',\n    isConnected: () => true,\n    getBalance: () => request('getBalance'),\n    debit(payload) {\n      validateBet(payload, true);\n      return request('debit', payload);\n    },\n    activateBet(payload) {\n      validateBet(payload, false);\n      return request('activateBet', payload);\n    },\n    credit(payload) {\n      validateBet(payload, true);\n      return request('credit', payload);\n    },\n    settleLoss(payload) {\n      validateBet(payload, false);\n      return request('settleLoss', payload);\n    },\n    subscribe(listener) {\n      if (typeof listener !== 'function') return () => {};\n      listeners.add(listener);\n      return () => listeners.delete(listener);\n    },\n    onCrashTarget(listener) {\n      if (typeof listener !== 'function') return () => {};\n      crashTargetListeners.add(listener);\n      return () => crashTargetListeners.delete(listener);\n    },\n    exit() {\n      sendToHost({ type: 'exit' });\n    },\n    _receive(message) {\n      if (!message || typeof message !== 'object') return;\n      if (message.type === 'wallet_response') {\n        const task = pending.get(message.id);\n        if (!task) return;\n        pending.delete(message.id);\n        global.clearTimeout(task.timeout);\n        if (!message.ok) {\n          task.reject(new Error(message.error || 'Opération du portefeuille refusée.'));\n          return;\n        }\n        try {\n          const snapshot = normalizeBalance(message.snapshot);\n          listeners.forEach(listener => listener(snapshot));\n          task.resolve(snapshot);\n        } catch (error) {\n          task.reject(error);\n        }\n      } else if (message.type === 'wallet_update') {\n        try {\n          const snapshot = normalizeBalance(message.snapshot);\n          listeners.forEach(listener => listener(snapshot));\n        } catch (_) {\n          // Une mise à jour mal formée ne doit pas bloquer l’interface du jeu.\n        }\n      } else if (message.type === 'bot_crash_target') {\n        crashTargetListeners.forEach(listener => listener(message));\n      }\n    }\n  };\n\n  global.AviatorWalletBridge = bridge;\n  global.__onexWalletReceive = message => bridge._receive(message);\n  global.addEventListener('message', event => {\n    const envelope = event.data;\n    if (envelope && envelope.__onexNativePayload) bridge._receive(envelope.__onexNativePayload);\n  });\n})(window);\n</script>\n  <script>const moneyText = value => Number(value).toFixed(2).replace(/\\.?0+$/, '');\nconst testMode = new URLSearchParams(window.location.search).has('test');\nconst quickAmounts = [200, 800, 2000, 6000, 20000, 70000];\nconst walletSessionId = `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;\nlet walletReady = false;\nconst startingRows = [\n  ['******41','x0','29675.98','0'],['******41','x0','19783.99','0'],['******35','x0','8141.66','0'],['******43','x0','5281.51','0'],\n  ['******41','x0','4941.85','0'],['******71','x0','4282.02','0'],['******19','x0','3802.69','0'],['******19','x0','3420.55','0'],\n  ['******08','x0','3112.24','0'],['******32','x0','2841.60','0'],['******96','x0','2460.88','0'],['******11','x0','2055.40','0'],\n  ['******83','x0','1970.21','0'],['******17','x0','1850.00','0'],['******61','x0','1645.75','0'],['******26','x0','1420.10','0'],\n  ['******54','x0','1198.42','0'],['******02','x0','940.00','0'],['******78','x0','810.50','0'],['******38','x0','625.20','0']\n];\nconst bets = [\n  { id: 1, amount: 400, state: 'ready', targetRound: null, win: 0 },\n  { id: 2, amount: 400, state: 'ready', targetRound: null, win: 0 }\n];\nconst playerCashoutTargets = [1.02, 1.08, 1.14, 1.21, 1.35, 1.50, 1.74, 2.10, 2.47, 3.18, 4.03, 5.07, 6.14, 8.82, 12.04, 21.47];\nlet simulatedPlayers = [];\nlet lastPlayerRowsRender = 0;\nlet nextBetId = 3;\nlet totalBetAmount = 1781268.6;\nlet totalWinAmount = 37282.44;\nlet publicBetCount = 2436;\nlet balance = 0;\nlet roundNumber = 1;\nlet phase = 'flight';\nlet phaseStart = Date.now();\nlet currentMultiplier = 1.49;\nlet displayedCrash = 3.18;\nlet videoFlightProfile = false;\nlet noticeTimer;\nlet autoEnabled = false;\nlet autoConfig = { base: 400, max: 0, cashout: 0, onWin: 'base', onLoss: 'base' };\nlet autoNextBet = 400;\nconst upcomingCrashes = [21.47, 3.18, 1.00, 5.07, 3.42, 1.04];\nlet crashCursor = 0;\nlet pendingBotCrashTarget = null;\nconst appliedBotCrashCommandIds = new Set();\nconst roundLength = 6800;\nconst COUNTDOWN_SECONDS = 4;\nconst COUNTDOWN_DISPLAY_LENGTH = COUNTDOWN_SECONDS * 1000;\nconst countdownLength = COUNTDOWN_DISPLAY_LENGTH;\nconst crashPause = 1900;\nconst countdownMarkerPositions = [[386,31],[348,29],[315,46],[300,79],[289,112]];\nconst countdownMarkerAngles = [108,77,48,18,0];\nconst horizontalDotBase = 50;\nconst horizontalDotSpacing = 73;\nconst horizontalDotSpeed = 18.3;\nconst verticalDotBase = 16;\nconst verticalDotSpacing = 22;\nconst verticalDotCount = 6;\nconst verticalDotSpeed = 9;\nlet chartDotOffsetX = 0;\nlet chartDotOffsetY = 0;\n\nconst cardsHost = document.getElementById('bet-cards');\nconst chart = document.querySelector('.game-scene');\nconst multiplierNode = document.getElementById('multiplier');\nconst countdownNode = document.getElementById('countdown');\nconst countdownIndicatorNode = document.getElementById('countdown-active-bar');\nconst countdownSegmentNodes = [\n  { node: document.getElementById('countdown-segment-4'), stage: 0 },\n  { node: document.getElementById('countdown-segment-3'), stage: 1 },\n  { node: document.getElementById('countdown-segment-2'), stage: 2 },\n  { node: document.getElementById('countdown-segment-1'), stage: 4 }\n];\nconst trailNode = document.getElementById('flight-trail');\nconst planeNode = document.getElementById('plane');\nconst flareNode = document.getElementById('crash-flare');\nconst noticeNode = document.getElementById('game-notice');\nconst acceptedBetNoticeNode = document.getElementById('countdown-accepted');\nconst videoCrashFrames = window.__CRASH_GAME_ASSETS__.crashFrames;\n\nfunction renderCards() {\n  cardsHost.innerHTML = '';\n  bets.forEach((bet, index) => {\n    const card = document.createElement('article');\n    card.className = 'bet-card';\n    card.classList.toggle('active-bet', bet.state === 'queued' || bet.state === 'live' || bet.state === 'cashed');\n    card.dataset.betId = String(bet.id);\n    const inputWrap = document.createElement('div');\n    inputWrap.className = 'bet-input-wrap';\n    const input = document.createElement('input');\n    input.className = 'bet-input';\n    input.type = 'number';\n    input.min = '200';\n    input.step = '1';\n    input.value = String(bet.amount);\n    input.setAttribute('aria-label', `Montant du pari ${index + 1}`);\n    input.disabled = !walletReady || bet.state !== 'ready' || Boolean(bet.processing);\n    input.addEventListener('input', () => { bet.amount = Math.max(0, Number(input.value) || 0); });\n    const clear = document.createElement('button');\n    clear.type = 'button';\n    clear.className = 'clear-input';\n    clear.textContent = '×';\n    clear.setAttribute('aria-label', 'Effacer le montant');\n    clear.disabled = !walletReady || bet.state !== 'ready' || Boolean(bet.processing);\n    clear.addEventListener('click', () => { input.value = ''; bet.amount = 0; input.focus(); });\n    inputWrap.append(input, clear);\n\n    const autoButton = document.createElement('button');\n    autoButton.type = 'button';\n    autoButton.className = 'auto-toggle';\n    autoButton.textContent = autoEnabled ? 'JEU AUTOMATIQUE ACTIF' : 'ACTIVER LE JEU AUTOMATIQUE';\n    autoButton.setAttribute('aria-label', 'Activer le jeu automatique');\n    autoButton.disabled = !walletReady || Boolean(bet.processing);\n    autoButton.addEventListener('click', openAutoModal);\n\n    const remove = document.createElement('button');\n    remove.type = 'button';\n    remove.className = 'remove-bet';\n    remove.textContent = '×';\n    remove.setAttribute('aria-label', 'Supprimer ce pari');\n    remove.disabled = Boolean(bet.processing) || bet.state === 'queued' || bet.state === 'live';\n    remove.addEventListener('click', () => {\n      if (bets.length <= 1) return;\n      const position = bets.findIndex(item => item.id === bet.id);\n      bets.splice(position, 1);\n      renderCards();\n    });\n\n    const quick = document.createElement('div');\n    quick.className = 'quick-bets';\n    quickAmounts.forEach(amount => {\n      const button = document.createElement('button');\n      button.type = 'button';\n      button.className = 'quick-bet';\n      button.textContent = String(amount);\n      button.setAttribute('aria-label', `Miser ${amount}`);\n      button.disabled = !walletReady || bet.state !== 'ready' || Boolean(bet.processing);\n      button.addEventListener('click', () => {\n        bet.amount = amount;\n        input.value = String(amount);\n      });\n      quick.append(button);\n    });\n\n    const action = document.createElement('button');\n    action.type = 'button';\n    action.className = 'action-button';\n    action.disabled = !walletReady || Boolean(bet.processing);\n    action.addEventListener('click', () => handleBetAction(bet));\n    if (bet.state === 'live') {\n      action.classList.add('cashout');\n      action.innerHTML = 'OBTENIR';\n    } else if (bet.state === 'cashed') {\n      action.classList.add('cashed');\n      action.textContent = 'PARI ACCEPTÉ';\n    } else if (bet.state === 'queued') {\n      action.classList.add('queued');\n      action.textContent = 'PARI ACCEPTÉ';\n    } else {\n      action.innerHTML = 'PLACER UN PARI<small>(sur le prochain tour)</small>';\n    }\n    card.append(inputWrap, autoButton, remove, quick, action);\n    cardsHost.append(card);\n  });\n  document.getElementById('add-bet').hidden = bets.length >= 3;\n}\n\nfunction applyWalletSnapshot(snapshot) {\n  const nextBalance = Number(snapshot?.amount);\n  if (!Number.isFinite(nextBalance) || nextBalance < 0) return;\n  balance = nextBalance;\n  document.getElementById('balance').textContent = `${moneyText(balance)} F`;\n  walletReady = true;\n  renderCards();\n}\n\nasync function recordStake(amount, bet, targetRound) {\n  if (!walletReady || !window.AviatorWalletBridge) throw new Error('Portefeuille indisponible.');\n  const result = await window.AviatorWalletBridge.debit({\n    requestId: `stake:${walletSessionId}:${targetRound}:${bet.id}`,\n    amount,\n    gameId: 'crash',\n    roundId: String(targetRound),\n    betId: String(bet.id)\n  });\n  applyWalletSnapshot(result);\n  totalBetAmount += amount;\n  publicBetCount += 1;\n  document.getElementById('total-bets').textContent = moneyText(totalBetAmount);\n  document.getElementById('bet-count').textContent = String(publicBetCount);\n  return result;\n}\n\nfunction queueStake(bet, targetRound) {\n  if (!walletReady || bet.processing) return Promise.resolve(false);\n  bet.processing = true;\n  renderCards();\n  return recordStake(bet.amount, bet, targetRound)\n    .then(() => {\n      bet.targetRound = targetRound;\n      bet.state = phase === 'flight' && roundNumber >= targetRound ? 'live' : 'queued';\n      if (bet.state === 'live') {\n        bet.targetRound = null;\n        void window.AviatorWalletBridge.activateBet({\n          requestId: `activate:${walletSessionId}:${targetRound}:${bet.id}`,\n          gameId: 'crash',\n          roundId: String(targetRound),\n          betId: String(bet.id)\n        }).catch(error => showNotice(error?.message || 'Mise non activée.', 'danger', 2600));\n      }\n      showNotice('Votre pari est accepté !', 'success', 1800);\n      return true;\n    })\n    .catch(error => {\n      bet.targetRound = null;\n      bet.state = 'ready';\n      showNotice(error?.message || 'Mise refusée par le portefeuille.', 'danger', 2600);\n      return false;\n    })\n    .finally(() => {\n      bet.processing = false;\n      renderCards();\n    });\n}\n\nfunction nextAutoAmount(won, currentAmount) {\n  const choice = won ? autoConfig.onWin : autoConfig.onLoss;\n  const requested = choice === 'double' ? currentAmount * 2 : autoConfig.base;\n  const limited = autoConfig.max >= 200 ? Math.min(requested, autoConfig.max) : requested;\n  return Math.max(200, limited);\n}\n\nasync function cashOutBet(bet) {\n  if (bet.state !== 'live' || bet.processing || phase !== 'flight' || currentMultiplier >= displayedCrash) return;\n  bet.processing = true;\n  renderCards();\n  const multiplier = currentMultiplier;\n  const payout = Math.round(bet.amount * multiplier * 100) / 100;\n  try {\n    const result = await window.AviatorWalletBridge.credit({\n      requestId: `cashout:${walletSessionId}:${roundNumber}:${bet.id}:${multiplier.toFixed(2)}`,\n      amount: payout,\n      betAmount: bet.amount,\n      multiplier,\n      gameId: 'crash',\n      roundId: String(roundNumber),\n      betId: String(bet.id)\n    });\n    applyWalletSnapshot(result);\n    bet.win = payout;\n    totalWinAmount += payout;\n    document.getElementById('total-wins').textContent = moneyText(totalWinAmount);\n    if (autoEnabled) autoNextBet = nextAutoAmount(true, bet.amount);\n    showNotice(`Vous avez gagné: ${moneyText(payout)} XAF`, 'success', 5000);\n    bet.state = 'ready';\n    bet.targetRound = null;\n  } catch (error) {\n    if (phase !== 'flight' || currentMultiplier >= displayedCrash) {\n      bet.state = 'ready';\n      bet.win = 0;\n    }\n    showNotice(error?.message || 'Gain non confirmé par le portefeuille.', 'danger', 2600);\n  } finally {\n    bet.processing = false;\n    renderCards();\n  }\n}\n\nfunction handleBetAction(bet) {\n  if (bet.processing || !walletReady) return;\n  if (bet.state === 'live') {\n    void cashOutBet(bet);\n  } else if (bet.state === 'ready') {\n    if (bet.amount < 200) {\n      showNotice('La mise minimale est de 200 XAF.', 'danger', 2200);\n      return;\n    }\n    void queueStake(bet, roundNumber + 1);\n  }\n  renderCards();\n}\n\nfunction showNotice(text, type, duration = 1600) {\n  clearTimeout(noticeTimer);\n  noticeNode.textContent = text;\n  noticeNode.className = `game-notice ${type}`;\n  noticeNode.hidden = false;\n  noticeTimer = setTimeout(() => { noticeNode.hidden = true; }, duration);\n}\n\nfunction flightDuration() {\n  if (videoFlightProfile) return 26000;\n  if (displayedCrash <= 1.05) return 2000;\n  const relativeCrash = Math.log(Math.max(1.01, displayedCrash)) / Math.log(3.18);\n  return roundLength * Math.max(0.08, relativeCrash);\n}\n\nfunction updateCountdownIndicator(elapsed) {\n  const progress = Math.max(0, Math.min(4, elapsed / 1000));\n  const index = Math.min(3, Math.floor(progress));\n  const fraction = progress - index;\n  const from = countdownMarkerPositions[index];\n  const to = countdownMarkerPositions[index + 1];\n  const x = from[0] + (to[0] - from[0]) * fraction;\n  const y = from[1] + (to[1] - from[1]) * fraction;\n  const angleFrom = countdownMarkerAngles[index];\n  const angleTo = countdownMarkerAngles[index + 1];\n  const angle = angleFrom + (angleTo - angleFrom) * fraction;\n  countdownIndicatorNode.setAttribute('transform', `translate(${x.toFixed(2)} ${y.toFixed(2)}) rotate(${angle.toFixed(1)})`);\n  countdownSegmentNodes.forEach(({ node, stage }) => {\n    const distanceAhead = stage - progress;\n    const opacity = stage === 4 ? 0.24 : distanceAhead <= 0.12 ? 0 : Math.min(0.84, 0.46 + distanceAhead * 0.18);\n    node.style.opacity = opacity.toFixed(2);\n  });\n}\n\nfunction setScene() {\n  chart.classList.toggle('is-crashed', phase === 'crash');\n  chart.classList.toggle('is-countdown', phase === 'countdown');\n  countdownNode.style.display = phase === 'countdown' ? 'inline' : 'none';\n  const showCountdownIndicator = phase === 'countdown' && Boolean(countdownNode.textContent);\n  document.getElementById('countdown-spinner').style.display = showCountdownIndicator ? 'inline' : 'none';\n  document.getElementById('countdown-indicator-overlay').style.display = showCountdownIndicator ? 'block' : 'none';\n  countdownIndicatorNode.style.display = showCountdownIndicator ? '' : 'none';\n  acceptedBetNoticeNode.hidden = phase !== 'countdown' || !bets.some(bet => bet.state === 'queued');\n  multiplierNode.style.display = phase === 'countdown' ? 'none' : '';\n  flareNode.style.opacity = phase === 'crash' ? '1' : '0';\n  if (phase === 'countdown') {\n    multiplierNode.textContent = '1.00x';\n    multiplierNode.style.opacity = '.82';\n  } else if (phase === 'crash') {\n    multiplierNode.textContent = `${displayedCrash.toFixed(2)}x`;\n    multiplierNode.style.opacity = '1';\n  } else {\n    multiplierNode.textContent = `${currentMultiplier.toFixed(2)}x`;\n    multiplierNode.style.opacity = '1';\n  }\n}\n\nfunction updateFlight(t) {\n  const progress = Math.max(0, Math.min(1, t / flightDuration()));\n  if (videoFlightProfile) {\n    const anchors = [[0,1],[1,1.02],[3,1.26],[5,1.74],[7,2.47],[10,4.03],[13,6.14],[16,8.82],[19,12.04],[22,15.83],[24,18.66],[26,21.47]];\n    const seconds = progress * 26;\n    const right = anchors.findIndex(point => point[0] >= seconds);\n    const hi = right < 0 ? anchors.length - 1 : right;\n    const lo = Math.max(0, hi - 1);\n    const mix = hi === lo ? 0 : (seconds - anchors[lo][0]) / (anchors[hi][0] - anchors[lo][0]);\n    currentMultiplier = anchors[lo][1] + (anchors[hi][1] - anchors[lo][1]) * mix;\n  } else {\n    currentMultiplier = 1 + (displayedCrash - 1) * Math.pow(progress, 1.66);\n  }\n  const position = videoFlightProfile\n    ? Math.max(0, Math.min(1, Math.log(Math.max(1, currentMultiplier)) / Math.log(21.47)))\n    : Math.max(0, Math.min(1, Math.pow(Math.max(0, (currentMultiplier - 1) / (3.42 - 1)), .48)));\n  const lowCurveCorrection = Math.min(1, position / 0.3);\n  let x, y, trailX, trailY, c1x, c1y, c2x, c2y;\n  if (videoFlightProfile) {\n    displayedCrash = 21.47;\n    const flightPoints = [[1,18,126],[1.02,48,121],[1.26,120,102],[1.74,190,77],[2.47,260,45],[4.03,330,34],[6.14,334,33],[8.82,336,34],[12.04,336,35],[15.83,337,36],[18.66,337,37],[21.47,337,40]];\n    const right = flightPoints.findIndex(point => point[0] >= currentMultiplier);\n    const hi = right < 0 ? flightPoints.length - 1 : right;\n    const lo = Math.max(0, hi - 1);\n    const mix = hi === lo ? 0 : (currentMultiplier - flightPoints[lo][0]) / (flightPoints[hi][0] - flightPoints[lo][0]);\n    x = flightPoints[lo][1] + (flightPoints[hi][1] - flightPoints[lo][1]) * mix;\n    y = flightPoints[lo][2] + (flightPoints[hi][2] - flightPoints[lo][2]) * mix;\n    trailX = Math.max(18, x - 25);\n    trailY = y + 11;\n    const curveStretch = Math.max(0, Math.min(1, (trailX - 95) / 210));\n    c1x = 18 + (trailX - 18) * (.32 + .13 * curveStretch);\n    c1y = 142;\n    c2x = 18 + (trailX - 18) * .76;\n    c2y = trailY + 14 + 35 * curveStretch;\n    flareNode.setAttribute('x', '294');\n    flareNode.setAttribute('y', '2');\n    flareNode.setAttribute('width', '87');\n    flareNode.setAttribute('height', '82');\n    flareNode.setAttribute('transform', 'translate(0 0)');\n  } else {\n    x = 18 + 310 * Math.pow(position, 0.854) - 7 * Math.min(1, position / 0.28) - 38 * Math.pow(1 - position, 2) * lowCurveCorrection;\n    y = 126 - position * 145 + position * position * 28 + 15.5 * Math.pow(1 - position, 2) * lowCurveCorrection;\n    trailX = x;\n    trailY = y;\n    c1x = 18 + position * 75;\n    c1y = 126 - position * 12;\n    c2x = 18 + position * 218;\n    c2y = 126 - position * 102;\n    flareNode.setAttribute('href', window.__CRASH_GAME_ASSETS__.crashSprite);\n    flareNode.setAttribute('x', '-18');\n    flareNode.setAttribute('y', '-28');\n    flareNode.setAttribute('width', '65');\n    flareNode.setAttribute('height', '54');\n    flareNode.setAttribute('transform', `translate(${x} ${y})`);\n  }\n  trailNode.setAttribute('d', `M18 ${videoFlightProfile ? 142 : 126} C${c1x} ${c1y} ${c2x} ${c2y} ${trailX} ${trailY}`);\n  planeNode.setAttribute('transform', `translate(${x} ${y + (videoFlightProfile ? 0 : 5 * (1 - position))}) rotate(${videoFlightProfile ? -18 : 0})`);\n}\n\nfunction applyBotCrashTarget(command) {\n  if (!command || typeof command.commandId !== 'string' || !command.commandId.trim()) return;\n  const target = command.target;\n  if (!Number.isFinite(target) || target < 1 || target > 1000 || appliedBotCrashCommandIds.has(command.commandId)) return;\n  appliedBotCrashCommandIds.add(command.commandId);\n  if (appliedBotCrashCommandIds.size > 128) appliedBotCrashCommandIds.delete(appliedBotCrashCommandIds.values().next().value);\n\n  const now = Date.now();\n  if (phase === 'flight' && !videoFlightProfile && target !== 21.47 && currentMultiplier < target) {\n    const normalizedMultiplier = Math.max(0, Math.min(1, (currentMultiplier - 1) / (target - 1)));\n    const progress = Math.pow(normalizedMultiplier, 1 / 1.66);\n    displayedCrash = target;\n    const nextDuration = flightDuration();\n    phaseStart = now - progress * nextDuration;\n    pendingBotCrashTarget = null;\n    const elapsed = now - phaseStart;\n    updateFlight(elapsed);\n    updateChartDots(elapsed, true);\n    setScene();\n    return;\n  }\n\n  pendingBotCrashTarget = target;\n}\n\nfunction tick() {\n  const now = Date.now();\n  const elapsed = now - phaseStart;\n  if (phase === 'flight') {\n    updateFlight(elapsed);\n    updateChartDots(elapsed, true);\n    if (autoEnabled && autoConfig.cashout >= 1.01) {\n      bets.forEach(bet => {\n        if (bet.state === 'live' && currentMultiplier >= autoConfig.cashout) {\n          cashOutBet(bet);\n          renderCards();\n        }\n      });\n    }\n    if (elapsed >= flightDuration()) {\n      phase = 'crash';\n      phaseStart = now;\n      currentMultiplier = displayedCrash;\n      if (videoFlightProfile) flareNode.setAttribute('href', videoCrashFrames[0]);\n      bets.forEach(bet => {\n        if (bet.state === 'live') {\n          void window.AviatorWalletBridge?.settleLoss({\n            requestId: `loss:${walletSessionId}:${roundNumber}:${bet.id}`,\n            gameId: 'crash',\n            roundId: String(roundNumber),\n            betId: String(bet.id)\n          }).catch(() => {});\n          if (!bet.processing) {\n            if (autoEnabled) autoNextBet = nextAutoAmount(false, bet.amount);\n            bet.state = 'ready';\n            bet.win = 0;\n          }\n        }\n      });\n      renderCards();\n      if (!videoFlightProfile) showNotice('Vous aurez plus de chance la prochaine fois !', 'danger', 2100);\n    }\n  } else if (phase === 'crash' && videoFlightProfile && elapsed < crashPause) {\n    const frameIndex = Math.min(videoCrashFrames.length - 1, Math.floor(elapsed / (crashPause / videoCrashFrames.length)));\n    flareNode.setAttribute('href', videoCrashFrames[frameIndex]);\n  } else if (phase === 'crash' && elapsed >= crashPause) {\n    phase = 'countdown';\n    phaseStart = now;\n    countdownNode.textContent = String(COUNTDOWN_SECONDS);\n    createSimulatedPlayers();\n    updateChartDots(0, false);\n    updateCountdownIndicator(0);\n    chart.classList.add('is-countdown');\n  } else if (phase === 'countdown') {\n    const remain = Math.max(1, COUNTDOWN_SECONDS - Math.floor(elapsed / 1000));\n    countdownNode.textContent = String(remain);\n    updateCountdownIndicator(elapsed);\n    if (elapsed >= countdownLength) {\n      phase = 'flight';\n      phaseStart = now;\n      roundNumber += 1;\n      displayedCrash = pendingBotCrashTarget ?? upcomingCrashes[crashCursor % upcomingCrashes.length];\n      pendingBotCrashTarget = null;\n      videoFlightProfile = displayedCrash === 21.47;\n      crashCursor += 1;\n      currentMultiplier = 1;\n      updateFlight(0);\n      updateChartDots(0, true);\n      bets.forEach(bet => {\n        if (bet.state === 'queued' && bet.targetRound <= roundNumber) {\n          bet.state = 'live';\n          bet.targetRound = null;\n          void window.AviatorWalletBridge.activateBet({\n            requestId: `activate:${walletSessionId}:${roundNumber}:${bet.id}`,\n            gameId: 'crash',\n            roundId: String(roundNumber),\n            betId: String(bet.id)\n          }).catch(error => showNotice(error?.message || 'Mise non activée.', 'danger', 2600));\n        } else if (bet.state === 'cashed') {\n          bet.state = 'ready';\n          bet.win = 0;\n          if (autoEnabled) {\n            bet.amount = autoNextBet;\n            bet.autoAttemptedRound = roundNumber;\n            void queueStake(bet, roundNumber);\n          }\n        } else if (bet.state === 'ready' && autoEnabled && !bet.processing && bet.autoAttemptedRound !== roundNumber) {\n          bet.amount = autoNextBet;\n          bet.autoAttemptedRound = roundNumber;\n          void queueStake(bet, roundNumber);\n        }\n      });\n      renderCards();\n    }\n  }\n  updateSimulatedPlayers(now);\n  setScene();\n}\n\nconst chartDotsXNode = document.getElementById('chart-dots-x');\nconst chartDotsYNode = document.getElementById('chart-dots-y');\nconst horizontalDots = [];\nconst verticalDots = [];\nfor (let i = 0; i < 8; i += 1) {\n  const dot = document.createElementNS('http://www.w3.org/2000/svg', 'circle');\n  dot.setAttribute('r', '2');\n  chartDotsXNode.append(dot);\n  horizontalDots.push(dot);\n}\nfor (let i = 0; i < verticalDotCount; i += 1) {\n  const dot = document.createElementNS('http://www.w3.org/2000/svg', 'circle');\n  dot.setAttribute('cx', '10');\n  dot.setAttribute('r', '2.1');\n  chartDotsYNode.append(dot);\n  verticalDots.push(dot);\n}\n\nfunction updateChartDots(elapsed = 0, scrolling = phase === 'flight') {\n  if (scrolling) {\n    const crashReference = Math.max(1.01, displayedCrash);\n    const oddsProgress = Math.max(0, Math.min(1,\n      Math.log(Math.max(1, currentMultiplier)) / Math.log(crashReference)\n    ));\n    // À mesure que la cote monte, les repères accélèrent pour renforcer\n    // l'impression de vitesse du vol sans déplacer les lignes de grille.\n    const motionRate = 1 + oddsProgress * 2.2;\n    const motionElapsed = elapsed / 1000 * motionRate;\n    chartDotOffsetX = (motionElapsed * horizontalDotSpeed) % horizontalDotSpacing;\n    chartDotOffsetY = (motionElapsed * verticalDotSpeed) % (verticalDotSpacing * verticalDotCount);\n  } else if (elapsed === 0) {\n    chartDotOffsetX = 0;\n    chartDotOffsetY = 0;\n  }\n  horizontalDots.forEach((dot, index) => {\n    dot.setAttribute('cx', String(horizontalDotBase + index * horizontalDotSpacing - chartDotOffsetX));\n    dot.setAttribute('cy', '130');\n  });\n  verticalDots.forEach((dot, index) => {\n    const cycle = verticalDotSpacing * verticalDotCount;\n    const y = verticalDotBase + ((index * verticalDotSpacing + chartDotOffsetY) % cycle);\n    dot.setAttribute('cy', String(y));\n  });\n}\nupdateChartDots(0, false);\n\nfunction renderRows(rows = startingRows) {\n  const rowsHost = document.getElementById('bet-rows');\n  rowsHost.innerHTML = '';\n  rows.forEach((row, index) => {\n    const line = document.createElement('div');\n    line.className = 'bet-row';\n    const colorClass = index % 6 === 0 ? 'positive' : '';\n    line.innerHTML = `<span>${row[0]}</span><span class=\"${colorClass}\">${row[1]}</span><span class=\"amount\">${row[2]} XAF</span><span class=\"gain\">${row[3]} XAF</span>`;\n    rowsHost.append(line);\n  });\n}\n\nfunction playerName(index, round) {\n  const suffix = String((41 + index * 17 + round * 13) % 90).padStart(2, '0');\n  return `******${suffix}`;\n}\n\nfunction createSimulatedPlayers() {\n  const betsByTarget = [200400, 200400, 160400, 94000, 70000, 60000, 20000, 20000, 6000, 2000, 2000, 800, 800, 400, 400, 200];\n  simulatedPlayers = playerCashoutTargets.map((target, index) => ({\n    name: playerName(index, roundNumber),\n    target,\n    bet: betsByTarget[index],\n    state: 'queued',\n    payout: 0\n  }));\n  renderSimulatedPlayers();\n}\n\nfunction renderSimulatedPlayers() {\n  const rowsHost = document.getElementById('bet-rows');\n  rowsHost.innerHTML = '';\n  simulatedPlayers.slice()\n    .sort((a, b) => (b.payout - a.payout) || (a.target - b.target))\n    .forEach(player => {\n      const line = document.createElement('div');\n      line.className = `bet-row player-${player.state}`;\n      const odds = player.state === 'cashed' ? `x${player.target.toFixed(2)}` : 'x0';\n      const payout = player.state === 'cashed' ? moneyText(player.payout) : '0';\n      line.innerHTML = `<span>${player.name}</span><span class=\"${player.state === 'cashed' ? 'positive' : ''}\">${odds}</span><span class=\"amount\">${moneyText(player.bet)} XAF</span><span class=\"gain\">${payout} XAF</span>`;\n      rowsHost.append(line);\n    });\n}\n\nfunction updateSimulatedPlayers(now) {\n  if (!simulatedPlayers.length) return;\n  if (phase === 'countdown') {\n    simulatedPlayers.forEach(player => {\n      player.state = 'queued';\n      player.payout = 0;\n    });\n  } else if (phase === 'flight') {\n    simulatedPlayers.forEach(player => {\n      if (player.state === 'queued') player.state = 'live';\n      if (player.state === 'live' && currentMultiplier >= player.target) {\n        player.state = 'cashed';\n        player.payout = Math.round(player.bet * player.target * 100) / 100;\n      }\n    });\n  } else if (phase === 'crash') {\n    simulatedPlayers.forEach(player => {\n      if (player.state === 'live' || player.state === 'queued') player.state = 'lost';\n    });\n  }\n  if (now - lastPlayerRowsRender >= 100 || phase !== 'flight') {\n    renderSimulatedPlayers();\n    lastPlayerRowsRender = now;\n  }\n}\n\nconst modalLayer = document.getElementById('modal-layer');\nconst rulesModal = document.getElementById('rules-modal');\nconst autoModal = document.getElementById('auto-modal');\nfunction openModal(modal) {\n  modalLayer.hidden = false;\n  rulesModal.hidden = modal !== rulesModal;\n  autoModal.hidden = modal !== autoModal;\n  document.body.style.overflow = 'hidden';\n}\nfunction closeModal() {\n  modalLayer.hidden = true;\n  rulesModal.hidden = true;\n  autoModal.hidden = true;\n  document.body.style.overflow = '';\n}\nfunction openAutoModal() {\n  document.getElementById('base-bet').value = String(autoConfig.base);\n  document.getElementById('max-bet').value = autoConfig.max || '';\n  document.getElementById('auto-cashout').value = autoConfig.cashout || '';\n  document.querySelector(`input[name=\"win-choice\"][value=\"${autoConfig.onWin}\"]`).checked = true;\n  document.querySelector(`input[name=\"loss-choice\"][value=\"${autoConfig.onLoss}\"]`).checked = true;\n  openModal(autoModal);\n}\ndocument.getElementById('open-rules').addEventListener('click', () => openModal(rulesModal));\ndocument.getElementById('add-bet').addEventListener('click', () => {\n  if (bets.length >= 3) return;\n  bets.push({ id: nextBetId++, amount: 400, state: 'ready', targetRound: null, win: 0 });\n  renderCards();\n});\ndocument.querySelectorAll('[data-close-modal]').forEach(button => button.addEventListener('click', closeModal));\ndocument.addEventListener('keydown', event => { if (event.key === 'Escape' && !modalLayer.hidden) closeModal(); });\ndocument.getElementById('auto-form').addEventListener('submit', event => {\n  event.preventDefault();\n  const requestedMax = Number(document.getElementById('max-bet').value) || 0;\n  autoConfig = {\n    base: Math.max(200, Number(document.getElementById('base-bet').value) || 400),\n    max: requestedMax >= 200 ? requestedMax : 0,\n    cashout: Number(document.getElementById('auto-cashout').value) || 0,\n    onWin: document.querySelector('input[name=\"win-choice\"]:checked').value,\n    onLoss: document.querySelector('input[name=\"loss-choice\"]:checked').value\n  };\n  if (autoConfig.max) autoConfig.base = Math.min(autoConfig.base, autoConfig.max);\n  autoNextBet = autoConfig.base;\n  autoEnabled = true;\n  bets.forEach(bet => {\n    if (bet.state === 'ready') {\n      bet.amount = autoNextBet;\n      bet.autoAttemptedRound = roundNumber + 1;\n      void queueStake(bet, roundNumber + 1);\n    }\n  });\n  renderCards();\n  closeModal();\n  showNotice('Jeu automatique activé.', 'success', 1800);\n});\ndocument.querySelectorAll('[data-clear]').forEach(button => button.addEventListener('click', () => {\n  const field = document.getElementById(button.dataset.clear);\n  field.value = '';\n  field.focus();\n}));\ndocument.getElementById('history-tab').addEventListener('click', event => {\n  event.currentTarget.classList.toggle('history-selected');\n  setTimeout(() => event.currentTarget.classList.remove('history-selected'), 450);\n});\n\ndocument.getElementById('balance').textContent = 'Connexion…';\nrenderCards();\nrenderRows();\ndocument.querySelector('.back-button')?.addEventListener('click', () => window.AviatorWalletBridge?.exit?.());\nif (window.AviatorWalletBridge) {\n  window.AviatorWalletBridge.onCrashTarget?.(applyBotCrashTarget);\n  window.AviatorWalletBridge.subscribe(applyWalletSnapshot);\n  window.AviatorWalletBridge.getBalance()\n    .then(applyWalletSnapshot)\n    .catch(error => showNotice(error?.message || 'Portefeuille indisponible.', 'danger', 5000));\n} else {\n  showNotice('Portefeuille indisponible.', 'danger', 5000);\n}\n\nconst visualPreset = (window.location.hash.slice(1) || 'play').toLowerCase();\nconst appShell = document.querySelector('.app-shell');\nconst referenceRows = {\n  countdown: [['******85','x0','929.55','0'],['******51','x0','800','0'],['******29','x0','722.03','0'],['******25','x0','575.79','0'],['******51','x0','464.78','0'],['******59','x0','400','0'],['******59','x0','400','0']],\n  accepted: [['******09','x0','1605.72','0'],['******81','x0','1584.46','0'],['******83','x0','1200','0'],['******57','x0','1176.02','0']],\n  cashout: [['******57','x0','1176.02','0'],['******79','x0','1134.22','0'],['******83','x0','1038.66','0'],['******39','x0','1025.83','0']],\n  crash104: [['******53','x0','1260.25','0'],['******57','x0','1176.02','0'],['******83','x0','1038.66','0'],['******47','x0','1000','0'],['******09','x0','1000','0'],['******61','x0','1000','0']]\n};\n\nfunction setReferenceStats(count, total, wins, shownBalance) {\n  publicBetCount = count;\n  totalBetAmount = total;\n  totalWinAmount = wins;\n  balance = shownBalance;\n  document.getElementById('bet-count').textContent = String(count);\n  document.getElementById('total-bets').textContent = moneyText(total);\n  document.getElementById('total-wins').textContent = moneyText(wins);\n  document.getElementById('balance').textContent = `${moneyText(balance)} F`;\n}\n\nfunction setReferenceCards(states) {\n  bets.splice(0, bets.length);\n  states.forEach((state, index) => bets.push({\n    id: index + 1,\n    amount: 400,\n    state,\n    targetRound: state === 'queued' ? roundNumber + 1 : null,\n    win: 0\n  }));\n  nextBetId = states.length + 1;\n  renderCards();\n}\n\nfunction setReferenceCountdown(number, states, stats, rowSet, dimmed = false) {\n  phase = 'countdown';\n  phaseStart = Date.now();\n  displayedCrash = 1;\n  currentMultiplier = 1;\n  setReferenceCards(states);\n  setReferenceStats(...stats);\n  renderRows(rowSet || startingRows);\n  countdownNode.textContent = number || '';\n  const referenceRemaining = Math.max(1, Math.min(5, Number(number) || 5));\n  updateCountdownIndicator((5 - referenceRemaining) * 1000);\n  updateChartDots(0, false);\n  if (!number) countdownNode.style.display = 'none';\n  setScene();\n  multiplierNode.style.display = 'none';\n  appShell.classList.toggle('reference-dim', dimmed);\n}\n\nfunction setReferenceFlight(multiplier, crash, states, stats, rowSet) {\n  phase = 'flight';\n  videoFlightProfile = false;\n  displayedCrash = crash;\n  const progress = crash <= 1.05 ? 0 : Math.pow((multiplier - 1) / (crash - 1), 1 / 1.66);\n  phaseStart = Date.now() - flightDuration() * Math.max(0, Math.min(1, progress));\n  setReferenceCards(states);\n  setReferenceStats(...stats);\n  renderRows(rowSet || startingRows);\n  const elapsed = flightDuration() * Math.max(0, Math.min(1, progress));\n  updateFlight(elapsed);\n  updateChartDots(elapsed, true);\n  setScene();\n  appShell.classList.remove('reference-dim');\n}\n\nfunction setReferenceNotice(text, type = 'success', duration = 60000) {\n  showNotice(text, type, duration);\n}\n\nif (visualPreset === 'play') {\n  phase = 'countdown';\n  phaseStart = Date.now();\n  currentMultiplier = 1;\n  displayedCrash = 21.47;\n  videoFlightProfile = true;\n  countdownNode.textContent = String(COUNTDOWN_SECONDS);\n  createSimulatedPlayers();\n  updateCountdownIndicator(0);\n  updateChartDots(0, false);\n  setScene();\n  renderCards();\n  const animateGame = () => {\n    tick();\n    if (testMode) window.setTimeout(animateGame, 16);\n    else window.requestAnimationFrame(animateGame);\n  };\n  if (testMode) window.setTimeout(animateGame, 0);\n  else window.requestAnimationFrame(animateGame);\n} else if (visualPreset === 'initial') {\n  const initialProgress = Math.pow((1.49 - 1) / (3.18 - 1), 1 / 1.66);\n  phase = 'flight';\n  displayedCrash = 3.18;\n  phaseStart = Date.now() - initialProgress * flightDuration();\n  updateFlight(initialProgress * flightDuration());\n  updateChartDots(initialProgress * flightDuration(), true);\n  setScene();\n} else if (visualPreset === 'countdown') {\n  setReferenceCountdown('7', ['queued','queued'], [39,36004.62,0,5427511.69], referenceRows.countdown, true);\n  setReferenceNotice('Votre pari est accepté !','success');\n} else if (visualPreset === 'accepted') {\n  setReferenceCountdown('', ['queued','queued','ready'], [2760,2283804.6,0,5427511.69], referenceRows.accepted, true);\n  setReferenceNotice('Votre pari est accepté !', 'success');\n} else if (visualPreset === 'rules') {\n  setReferenceCountdown('', ['ready','ready','ready'], [1038,518125.34,0,5427511.69], startingRows);\n  openModal(rulesModal);\n} else if (visualPreset === 'flightstart' || visualPreset === 'round-start') {\n  setReferenceFlight(1.00,3.18,['live','live','ready'],[2760,2283804.6,0,5427511.69],referenceRows.accepted);\n} else if (visualPreset === 'flight106') {\n  setReferenceFlight(1.06,3.18,['live','live','ready'],[2760,2283804.6,0,5427511.69],referenceRows.accepted);\n} else if (visualPreset === 'auto-early' || visualPreset === 'auto30' || visualPreset === 'flight126') {\n  setReferenceFlight(1.26,5.07,['queued','queued'],[2760,2611214.68,3013.08,5427511.69]);\n  setReferenceNotice('Bet on the next round has been accepted','success-early');\n  if (visualPreset !== 'flight126') openAutoModal();\n} else if (visualPreset === 'highflight') {\n  setReferenceFlight(5.07,5.07,['ready','ready','ready'],[2760,2611214.68,3013.08,5427511.69]);\n} else if (visualPreset === 'live') {\n  setReferenceFlight(2.74,3.42,['live','live','ready'],[4698,2649996,1479361.5,5427511.69],referenceRows.cashout);\n} else if (visualPreset === 'cashed') {\n  setReferenceFlight(3.23,3.42,['live','live','ready'],[4698,2649996,1841592.42,5428451.69],referenceRows.cashout);\n  setReferenceNotice('Vous avez gagné: 940 XAF','success');\n} else if (visualPreset === 'crash342') {\n  videoFlightProfile = false;\n  phase = 'crash';\n  displayedCrash = 3.42;\n  setReferenceCards(['cashed','ready','ready']);\n  setReferenceStats(4698,2649996,1841592.42,5428451.69);\n  renderRows(referenceRows.cashout);\n  updateFlight(flightDuration());\n  updateChartDots(flightDuration(), true);\n  setScene();\n  setReferenceNotice('Vous aurez plus de chance la prochaine fois !','danger');\n  appShell.classList.remove('reference-dim');\n} else if (visualPreset === 'crash') {\n  videoFlightProfile = false;\n  phase = 'crash';\n  displayedCrash = 1;\n  currentMultiplier = 1;\n  setReferenceCards(['ready','ready','ready']);\n  setReferenceStats(2760,2283804.6,0,5427511.69);\n  renderRows(referenceRows.accepted);\n  updateFlight(0);\n  updateChartDots(0, false);\n  setScene();\n  setReferenceNotice('Vous aurez plus de chance la prochaine fois !','danger');\n  appShell.classList.remove('reference-dim');\n} else if (visualPreset === 'crash104') {\n  videoFlightProfile = false;\n  phase = 'crash';\n  displayedCrash = 1.04;\n  setReferenceCards(['ready','ready']);\n  setReferenceStats(4572,4463392.68,0,5426451.69);\n  renderRows(referenceRows.crash104);\n  updateFlight(flightDuration());\n  updateChartDots(flightDuration(), true);\n  setScene();\n  setReferenceNotice('Vous aurez plus de chance la prochaine fois !','danger');\n} else if (visualPreset === 'final-countdown' || visualPreset === 'countdown-final') {\n  setReferenceCountdown('7',['queued','queued','ready'],[4572,4463392.68,0,5426451.69],referenceRows.crash104,true);\n  setReferenceNotice('Votre pari est accepté !','success');\n} else if (visualPreset === 'auto' || visualPreset === 'auto-final') {\n  setReferenceCountdown('1', ['queued','queued','ready'], [2736,2130017.76,0,5426511.69]);\n  setReferenceNotice('Votre pari est accepté !','success');\n  openAutoModal();\n} else if (visualPreset === 'video-crash' || visualPreset === 'video-explosion') {\n  phase = 'crash';\n  videoFlightProfile = true;\n  displayedCrash = 21.47;\n  currentMultiplier = 21.47;\n  setReferenceCards(['ready','ready']);\n  setReferenceStats(2760,2283804.6,0,5427511.69);\n  renderRows(referenceRows.accepted);\n  updateFlight(flightDuration());\n  updateChartDots(flightDuration(), true);\n  flareNode.setAttribute('href', visualPreset === 'video-explosion' ? videoCrashFrames[0] : videoCrashFrames[3]);\n  setScene();\n  noticeNode.hidden = true;\n  appShell.classList.remove('reference-dim');\n} else {\n  setInterval(tick, 160);\n}\n</script>\n</body>\n</html>\n";
